package app.kinnect.live;
import android.app.*;import android.os.*;import android.content.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

/** Server-authorized economy settings. No client-side balance mutation or checkout enablement. */
public final class EconomyAdminActivity extends Activity {
 private CommerceUi ui;private JSONObject draft;private JSONArray audit;private int version;private String tab="coins";private LinearLayout body;private final Map<String,EditText> fields=new LinkedHashMap<>();private final List<EditText> packs=new ArrayList<>();private boolean saving;
 protected void attachBaseContext(Context c){super.attachBaseContext(I18n.localized(c));}
 public void setContentView(View v){super.setContentView(CommerceChrome.wrap(this,v));}
 public void onCreate(Bundle b){super.onCreate(b);ui=new CommerceUi(this);getWindow().setStatusBarColor(ui.bg);getWindow().setNavigationBarColor(ui.bg);getWindow().getDecorView().setSystemUiVisibility(WebTheme.isDark(this)?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);NativeApi.shared.initialize(this,ServerConfig.DEFAULT_ORIGIN);load();}
 private void toast(String value){Toast.makeText(this,I18n.t(value),Toast.LENGTH_SHORT).show();}
 private void load(){LinearLayout loading=ui.col();loading.setBackgroundColor(ui.bg);loading.addView(ui.header("Kinh tế & Quà Live"));loading.addView(ui.empty("wallet","Đang tải…"));setContentView(loading);NativeApi.shared.call("GET","/api/admin/economy",null,(data,error,status)->{if(isFinishing()||isDestroyed())return;if(error!=null){loading.removeViewAt(1);loading.addView(ui.empty("shield_check",status==403?"Chỉ dành cho admin":"Chưa tải được cấu hình"));return;}draft=data.optJSONObject("config");version=data.optInt("version");audit=data.optJSONArray("audit");draw();});}
 private EditText field(LinearLayout parent,String label,String key,long value){LinearLayout row=ui.row();TextView name=ui.text(label,13,ui.ink,false);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));EditText input=new KinnectInput(this);input.setText(String.valueOf(value));input.setTextColor(ui.purple);input.setTextSize(14);input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(7)});input.setPadding(ui.dp(10),ui.dp(10),ui.dp(10),ui.dp(10));input.setBackground(ui.round(ui.soft,12));input.setContentDescription(I18n.t(label));input.setTag("economy:"+key);row.addView(input,new LinearLayout.LayoutParams(ui.dp(94),ui.dp(48)));ui.add(parent,row,10);fields.put(key,input);return input;}
 private void toggle(LinearLayout parent,String label,String key){android.widget.Switch control=new android.widget.Switch(this);control.setText(I18n.t(label));control.setTextSize(13);control.setTextColor(ui.ink);control.setPadding(0,ui.dp(12),0,ui.dp(12));control.setChecked(draft.optBoolean(key));control.setOnCheckedChangeListener((v,on)->{try{draft.put(key,on);}catch(JSONException ignored){}});parent.addView(control,new LinearLayout.LayoutParams(-1,-2));}
 private boolean collect(){try{for(Map.Entry<String,EditText> f:fields.entrySet()){long value=Long.parseLong(f.getValue().getText().toString().trim());if(f.getKey().startsWith("gift:"))draft.getJSONObject("giftPrices").put(f.getKey().substring(5),value);else draft.put(f.getKey(),value);}if(tab.equals("packs")){JSONArray values=new JSONArray();for(EditText input:packs)values.put(Long.parseLong(input.getText().toString().trim()));draft.put("coinPacks",values);}return true;}catch(Exception e){toast("Kiểm tra lại các giá trị.");return false;}}
 private void draw(){fields.clear();packs.clear();LinearLayout root=ui.col();root.setBackgroundColor(ui.bg);root.addView(ui.header("Kinh tế & Quà Live",ui.icon("rotate_ccw","Tải lại",this::load),ui.icon("history","Lịch sử chỉnh sửa",this::history)));LinearLayout tabs=ui.row();tabs.setPadding(ui.dp(16),0,ui.dp(16),ui.dp(8));for(String key:new String[]{"coins","gifts","packs"}){Button b=ui.action(key.equals("coins")?"Xu":key.equals("gifts")?"Quà Live":"Gói nạp",null,()->{if(collect()){tab=key;draw();}});if(!tab.equals(key)){b.setBackground(ui.round(ui.soft,14));b.setTextColor(ui.purple);}LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(0,-2,1);at.setMargins(ui.dp(3),0,ui.dp(3),0);tabs.addView(b,at);}root.addView(tabs);ScrollView scroll=new ScrollView(this);body=ui.col();body.setPadding(ui.dp(18),0,ui.dp(18),ui.dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  if(tab.equals("coins")){ui.add(body,ui.action("Tặng xu thành viên","gift",()->ui.go(CoinGrantActivity.class)),8);field(body,"đ / xu","vndPerCoin",draft.optLong("vndPerCoin"));field(body,"Xu chào mừng","signupBonusCoins",draft.optLong("signupBonusCoins"));toggle(body,"Tặng xu khi đăng ký","signupBonusEnabled");ui.add(body,ui.text("Chỉ áp dụng cho tài khoản đăng ký mới. Xu tặng không rút thành tiền.",12,ui.muted,false),12);}
  else if(tab.equals("gifts")){toggle(body,"Quà trải nghiệm","trialGiftsEnabled");JSONObject prices=draft.optJSONObject("giftPrices");for(String[] gift:LiveGiftExperience.GIFTS){LinearLayout card=ui.section();field(card,gift[1],"gift:"+gift[0],prices==null?0:prices.optLong(gift[0]));ui.add(body,card,10);}}
  else{toggle(body,"Hiện mệnh giá nạp","showCoinPacks");JSONArray values=draft.optJSONArray("coinPacks");for(int i=0;values!=null&&i<values.length();i++){final int index=i;LinearLayout card=ui.section();EditText input=field(card,"Xu","pack:"+i,values.optLong(i));fields.remove("pack:"+i);packs.add(input);long vnd=values.optLong(i)*draft.optLong("vndPerCoin");LinearLayout foot=ui.row();foot.addView(ui.text(java.text.NumberFormat.getIntegerInstance(new java.util.Locale("vi","VN")).format(vnd)+"đ",12,ui.muted,false),new LinearLayout.LayoutParams(0,-2,1));foot.addView(ui.icon("trash_2","Xóa mệnh giá",()->{if(!collect())return;JSONArray old=draft.optJSONArray("coinPacks"),next=new JSONArray();for(int n=0;n<old.length();n++)if(n!=index)next.put(old.optLong(n));try{draft.put("coinPacks",next);}catch(Exception ignored){}draw();}),new LinearLayout.LayoutParams(ui.dp(44),ui.dp(44)));card.addView(foot);ui.add(body,card,10);}if(packs.size()<12)ui.add(body,ui.action("Thêm mệnh giá","plus",()->{if(!collect())return;draft.optJSONArray("coinPacks").put(100);draw();}),12);ui.add(body,ui.text("Thanh toán thật chưa kết nối.",12,ui.muted,false),12);}
  Button save=ui.action("Lưu","check",this::save);save.setTag("economy:save");save.setEnabled(!saving);LinearLayout footer=ui.col();footer.setPadding(ui.dp(18),ui.dp(10),ui.dp(18),ui.dp(12));footer.addView(save,new LinearLayout.LayoutParams(-1,-2));root.addView(footer);setContentView(root);
 }
 private void save(){if(saving||!collect())return;saving=true;try{JSONObject payload=new JSONObject().put("version",version).put("config",draft);NativeApi.shared.call("PATCH","/api/admin/economy",payload,(data,error,status)->{saving=false;if(isFinishing()||isDestroyed())return;if(error!=null){toast(error);return;}toast("Đã lưu cấu hình");load();});}catch(JSONException e){saving=false;toast("Chưa lưu được cấu hình.");}}
 private void history(){LinearLayout list=ui.col();if(audit==null||audit.length()==0)list.addView(ui.empty("history","Chưa có chỉnh sửa"));else for(int i=0;i<audit.length();i++){JSONObject entry=audit.optJSONObject(i);if(entry==null)continue;TextView item=ui.text("#"+entry.optInt("version")+" · "+entry.optString("actor")+"\n"+new java.text.SimpleDateFormat("dd/MM HH:mm",java.util.Locale.getDefault()).format(new java.util.Date(entry.optLong("created"))),13,ui.ink,false);item.setPadding(0,ui.dp(10),0,ui.dp(10));list.addView(item);}ScrollView scroll=new ScrollView(this);scroll.addView(list);scroll.setLayoutParams(new LinearLayout.LayoutParams(-1,Math.min(ui.dp(350),getResources().getDisplayMetrics().heightPixels/2)));new Sheet(this).setTitle(I18n.t("Lịch sử chỉnh sửa")).setView(scroll).setPositiveButton(I18n.t("Đóng"),null).show();}
}
